sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || !newValue) {
        return;
    }

    var startDateValue = g_form.getValue('start_date');
    var endDateValue = g_form.getValue('end_date');

    if (!startDateValue || !endDateValue) {
        return;
    }

    var startDate = new Date(startDateValue);
    var endDate = new Date(endDateValue);

    if (startDate > endDate) {

        g_form.addErrorMessage(
            'End Date cannot be before Start Date.'
        );

        return;
    }

    var weekendDays = 0;
    var checkDate = new Date(startDate);

    while (checkDate <= endDate) {

        var day = checkDate.getDay();

        // Saturday = 6
        // Sunday = 0
        if (day === 0 || day === 6) {
            weekendDays++;
        }

        checkDate.setDate(
            checkDate.getDate() + 1
        );
    }

    if (weekendDays > 0) {

        g_form.addInfoMessage(
            '⚠️ Your selected leave period includes ' +
            weekendDays +
            ' weekend day(s). Weekend days will not be counted as leave.'
        );
    }
}
